  const client = await setupClient();

  await client.sendHello('harbor/test-build');

  const ok = await client.sendRequest('job.start', { cwd: '/tmp', cols: 80, rows: 24 });

  expect(ok['job']).toMatchObject({ runner: 'claude' });
