test('it lists a started job with the model it was started with', async () => {
  const client = await setupClient();

  await client.sendHello('harbor/test-build');

  const ok = await client.sendRequest('job.start', { cwd: '/tmp', model: 'fast', cols: 80, rows: 24 });

  expect(ok['job']).toMatchObject({ model: 'fast' });

  const list = await client.sendRequest('job.list');

  expect(list).toMatchObject({ jobs: [{ model: 'fast' }] });
});

test('it lists a started job without a model key when it runs the default', async () => {
  const client = await setupClient();

  await client.sendHello('harbor/test-build');

  await client.sendRequest('job.start', { cwd: '/tmp', cols: 80, rows: 24 });

  const list = await client.sendRequest('job.list');

  const listed = (list['jobs'] as unknown[])[0];

  expect(listed).toBeObject();
  expect(Object.keys(listed as object)).not.toInclude('model');
});

