test('it reports canEject as false when the descriptor omits it', () => {
  const mirror = toMirrorJob(buildDescriptor());

  if (mirror === null) {
    throw new Error('expected a mirror job');
  }

  expect(mirror.canEject).toBe(false);
});

test('it reads the host from the descriptor locator', () => {
  const mirror = toMirrorJob(buildDescriptor({ locator: { daemonID: 'd-1', hostID: 'edge-1' } }));

  if (mirror === null) {
    throw new Error('expected a mirror job');
  }

  expect(mirror.host).toBe('edge-1');
});

test('it falls back the host to local when the descriptor carries no locator', () => {
  const mirror = toMirrorJob(buildDescriptor());

  if (mirror === null) {
    throw new Error('expected a mirror job');
  }

  expect(mirror.host).toBe('local');
});

test('it keeps the model the job was started with', () => {
  const mirror = toMirrorJob(buildDescriptor({ model: 'fast' }));

  if (mirror === null) {
    throw new Error('expected a mirror job');
  }

  expect(mirror.model).toBe('fast');
});

test('it derives the lifecycle from the alive flag when the descriptor omits it', () => {
  const dead = toMirrorJob(buildDescriptor({ alive: false }));

  if (dead === null) {
    throw new Error('expected a mirror job');
  }

  expect(dead.lifecycle).toBe('exited');
});

